{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.knot_inventory_report as WITH inv_sent AS ( SELECT (SPLIT_PART(UPPER(TRIM(factsss.sku)), \'-\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(factsss.sku)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(factsss.sku)), \'-\', ARRAY_SIZE(SPLIT(UPPER(TRIM(factsss.sku)), \'-\')))) AS sku, COALESCE( TO_DATE(sheet.SLOT_DATE, \'DD/MM/YYYY\'), TO_DATE(sheet.ORDER_DATE, \'DD/MM/YYYY\'), factsss.ORDER_DATE ) AS inward_date, SUM(factsss.SUBORDER_QUANTITY) AS qty_sent FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate AS factsss LEFT JOIN snitch_db.maplemonk.gs_mpforwards_sheet1 AS sheet ON factsss.order_id = sheet.SO_NUMBER AND sheet.MARKETPLACE = \'KNOT\' WHERE factsss.MARKETPLACE_MAPPED = \'KNOT\' AND factsss.SALE_ORDER_ITEM_STATUS NOT IN (\'CANCELLED\', \'UNFULFILLABLE\') GROUP BY 1, 2 ), pullback AS ( SELECT (SPLIT_PART(UPPER(TRIM(sku)), \'-\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(sku)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(sku)), \'-\', ARRAY_SIZE(SPLIT(UPPER(TRIM(sku)), \'-\')))) AS sku, TO_DATE(TRIM(date), \'DD-MM-YYYY\') AS outward_date, SUM(TRY_TO_NUMBER(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Pullback Inv\"))) AS pullback_inventory FROM snitch_db.maplemonk.s3_knot_pullback GROUP BY 1, 2 ), min_dates AS ( SELECT sku, MIN(inward_date) AS first_inward_date FROM inv_sent GROUP BY 1 ), date_expanded AS ( SELECT m.sku, DATEADD(DAY, s.seq, m.first_inward_date) AS generated_date FROM min_dates m, LATERAL ( SELECT SEQ4() AS seq FROM TABLE(GENERATOR(ROWCOUNT => 10000)) ) s WHERE DATEADD(DAY, s.seq, m.first_inward_date) <= CURRENT_DATE() + 1 ), main_data AS ( SELECT sku, generated_date AS date FROM date_expanded ), sales AS ( SELECT (SPLIT_PART(UPPER(TRIM(sku)), \'-\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(sku)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(sku)), \'-\', ARRAY_SIZE(SPLIT(UPPER(TRIM(sku)), \'-\')))) AS sku, order_date, SUM(TOTAL_QUANTITY) AS sales_qty, SUM(RETURN_QUANTITY) AS ret_qty FROM snitch_db.maplemonk.knot_fact_item GROUP BY 1, 2 ), base_data AS ( SELECT sku, date, first_inward_date, SUM(qty_sent) AS qty_sent, SUM(sales_qty) AS sales_qty, SUM(ret_qty) AS ret_qty, SUM(pullback_inventory) AS pullback_inventory FROM ( SELECT COALESCE(a.sku, c.sku) AS sku, COALESCE(a.date, e.first_inward_date) AS date, COALESCE(b.qty_sent, 0) AS qty_sent, COALESCE(c.sales_qty, 0) AS sales_qty, COALESCE(c.ret_qty, 0) AS ret_qty, COALESCE(k.pullback_inventory, 0) AS pullback_inventory, e.first_inward_date FROM main_data a LEFT JOIN inv_sent b ON a.date = b.inward_date AND a.sku = b.sku FULL OUTER JOIN sales c ON a.date = c.order_date AND a.sku = c.sku LEFT JOIN pullback k ON a.date = k.outward_date AND a.sku = k.sku LEFT JOIN min_dates e ON COALESCE(a.sku, c.sku) = e.sku ) GROUP BY 1, 2, 3 ) , ordered_data AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date FROM base_data ) , initial_rows AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date, 0 AS closing_inventory, qty_sent AS opening_inventory, qty_sent - sales_qty + ret_qty - pullback_inventory AS closing_inventory_new FROM ordered_data WHERE (sku, date) IN ( SELECT sku, MIN(date) FROM ordered_data GROUP BY sku ) ), recursive_inventory AS ( SELECT * FROM initial_rows UNION ALL SELECT curr.sku, curr.date, curr.qty_sent, curr.sales_qty, curr.ret_qty, curr.pullback_inventory, curr.first_inward_date, prev.closing_inventory_new AS closing_inventory, prev.closing_inventory_new + curr.qty_sent AS opening_inventory, prev.closing_inventory_new + curr.qty_sent - curr.sales_qty + curr.ret_qty - curr.pullback_inventory AS closing_inventory_new FROM recursive_inventory prev JOIN ordered_data curr ON curr.sku = prev.sku AND curr.date = DATEADD(DAY, 1, prev.date) ), with_sku_group AS ( SELECT *, REGEXP_REPLACE(sku, \'-[^-]*$\', \'\') AS sku_group, SPLIT_PART(sku, \'-\', ARRAY_SIZE(SPLIT(sku, \'-\'))) AS size FROM recursive_inventory ), latest_metafields AS ( SELECT * FROM ( SELECT *, (SPLIT_PART(UPPER(TRIM(sku_group)), \'-\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(sku_group)), \'-\', 2)) as clean_sku_group, ROW_NUMBER() OVER (PARTITION BY clean_sku_group ORDER BY status DESC) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) SELECT w.sku, w.sku_group, w.size, w.date, w.qty_sent, w.sales_qty, w.ret_qty, w.pullback_inventory, w.first_inward_date, w.opening_inventory, w.closing_inventory_new AS closing_inventory, m.category, m.title, m.material_new, m.print_design, m.fit, m.sleeve_type, m.collar_new FROM with_sku_group w LEFT JOIN latest_metafields m ON w.sku_group = m.clean_sku_group ORDER BY w.sku, w.date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            